
import{actionLabel}from './action-icons.js';
import{esc}from './ui.js';
import{RUQYAH_RECORDINGS,ruqyahFor,ruqyahDuration}from './ruqyah-catalog.js';
import{ruqyahPlayback}from './ruqyah-session.js';
export{RUQYAH_RECORDINGS,ruqyahFor,ruqyahDuration}from './ruqyah-catalog.js';
export function ruqyahMarkup(reciter){const records=ruqyahFor(reciter);if(!records.length)return '';return '<section class="reciter-ruqyah" aria-label="Рукъя"><div class="ruqyah-heading"><span class="eyebrow">ОТДЕЛЬНОЕ ЧТЕНИЕ</span><h2>Рукъя</h2></div>'+records.map(r=>'<article class="ruqyah-recording" data-ruqyah="'+r.id+'"><p>'+esc(r.title)+' <span class="ruqyah-duration">'+ruqyahDuration(r.duration)+'</span></p><div class="ruqyah-actions"><button type="button" class="button" data-ruqyah-play aria-pressed="false">'+actionLabel('play','Слушать')+'</button><a class="button secondary" href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer" download="salah-ruqyah-'+r.id+'.mp3">'+actionLabel('download','Скачать файл')+'</a></div><p class="ruqyah-status" role="status"></p></article>').join('')+'</section>';}
export function bindRuqyah(host,{session=ruqyahPlayback}={}){const cleanup=[];for(const node of host.querySelectorAll('[data-ruqyah]')){const record=RUQYAH_RECORDINGS.find(r=>r.id===node.dataset.ruqyah);if(!record)continue;const button=node.querySelector('[data-ruqyah-play]'),status=node.querySelector('.ruqyah-status');const play=()=>session.start(record.id);button.addEventListener('click',play);const unsubscribe=session.subscribe(state=>{const own=state.record?.id===record.id,active=own&&['playing','loading'].includes(state.status);button.innerHTML=actionLabel(active?'pause':'play',active?'Пауза':'Слушать');button.setAttribute('aria-pressed',String(active));status.textContent=own?({loading:'Открываем запись…',paused:'На паузе',ended:'Запись завершена',error:'Не удалось открыть запись. Попробуйте снова.'}[state.status]||''):'';});cleanup.push(()=>{unsubscribe();button.removeEventListener('click',play);});}return()=>{for(const fn of cleanup)fn();};}
